bool SmbFsDelegateStubDispatch::Accept(
    SmbFsDelegate* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kSmbFsDelegate_RequestCredentials_Name: {
      break;
    }
  }
  return false;
}

// static
bool SmbFsDelegateStubDispatch::AcceptWithResponder(
    SmbFsDelegate* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kSmbFsDelegate_RequestCredentials_Name: {

      internal::SmbFsDelegate_RequestCredentials_Params_Data* params =
          reinterpret_cast<
              internal::SmbFsDelegate_RequestCredentials_Params_Data*>(
                  message->mutable_payload());
      
      bool success = true;
      SmbFsDelegate_RequestCredentials_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SmbFsDelegate::Name_, 0, false);
        return false;
      }
      SmbFsDelegate::RequestCredentialsCallback callback =
          SmbFsDelegate_RequestCredentials_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->RequestCredentials(std::move(callback));
      return true;
    }
  }
  return false;
}


