bool StructTraits<::smbfs::mojom::Password::DataView, ::smbfs::mojom::PasswordPtr>::Read(
    ::smbfs::mojom::Password::DataView input,
    ::smbfs::mojom::PasswordPtr* output) {
  bool success = true;
  ::smbfs::mojom::PasswordPtr result(::smbfs::mojom::Password::New());
  
      if (success)
        result->fd = input.TakeFd();
      if (success)
        result->length = input.length();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::smbfs::mojom::KerberosConfig::DataView, ::smbfs::mojom::KerberosConfigPtr>::Read(
    ::smbfs::mojom::KerberosConfig::DataView input,
    ::smbfs::mojom::KerberosConfigPtr* output) {
  bool success = true;
  ::smbfs::mojom::KerberosConfigPtr result(::smbfs::mojom::KerberosConfig::New());
  
      if (success && !input.ReadSource(&result->source))
        success = false;
      if (success && !input.ReadIdentity(&result->identity))
        success = false;
  *output = std::move(result);
  return success;
}


