SmbFsBootstrapAsyncWaiter::SmbFsBootstrapAsyncWaiter(
    SmbFsBootstrap* proxy) : proxy_(proxy) {}

SmbFsBootstrapAsyncWaiter::~SmbFsBootstrapAsyncWaiter() = default;

void SmbFsBootstrapAsyncWaiter::MountShare(
    MountOptionsPtr options, ::mojo::PendingRemote<SmbFsDelegate> delegate, MountError* out_error, ::mojo::PendingRemote<SmbFs>* out_smbfs) {
  base::RunLoop loop;
  proxy_->MountShare(std::move(options),std::move(delegate),
      base::BindOnce(
          [](base::RunLoop* loop,
             MountError* out_error
,
             ::mojo::PendingRemote<SmbFs>* out_smbfs
,
             MountError error,
             ::mojo::PendingRemote<SmbFs> smbfs) {*out_error = std::move(error);*out_smbfs = std::move(smbfs);
            loop->Quit();
          },
          &loop,
          out_error,
          out_smbfs));
  loop.Run();
}



